cypress_script:
describe('Opening links in new windows', () => {
  it('should open a new window when the link is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.get('a').contains('Click Here').click();
    cy.url().should('not.eq', 'https://the-internet.herokuapp.com/windows');
  });

  it('should remain on the same page when the link is not clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/windows');
    cy.get('div#content').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Opening links in new windows', () => {
  test('should open a new window when the link is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    const [newPage] = await Promise.all([
      page.waitForEvent('popup'),
      page.click('text=Click Here')
    ]);
    expect(newPage.url()).not.toBe('https://the-internet.herokuapp.com/windows');
  });

  test('should remain on the same page when the link is not clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/windows');
    await expect(page.locator('div#content')).toBeVisible();
  });
});
